pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(1000, "Token", "TKN");
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000);
        uint256 supplyBefore = c.totalSupply();
        c.burn(amount);
        uint256 supplyAfter = c.totalSupply();
        assertEq(supplyBefore - supplyAfter, amount);
    }
}
